        continue
    if tag.startswith('/'):
        closing = tag[1:]
        if not stack:
            print('Unexpected close tag:', closing)
        elif stack[-1] != closing:
            print(f'Mismatched close tag: expected </{stack[-1]}>, got </{closing}>')
